import React from "react";
import "./ConfirmModal.css";

const ConfirmPurchaseModal = ({ show, onConfirm, onClose }) => {
    if (!show) return null;

    const handleBackdropClick = (e) => {
        if (e.target.classList.contains("custom-modal-overlay")) onClose?.();
    };

    return (
        <>
            <div className="modal-backdrop fade show cm-backdrop"></div>

            <div
                className="custom-modal-overlay d-flex align-items-center justify-content-center"
                onClick={handleBackdropClick}
                role="dialog"
                aria-modal="true"
                aria-labelledby="cm-title"
            >
                <div className="modal-dialog" onClick={(e) => e.stopPropagation()}>
                    <div className="modal-content border-0 shadow-lg rounded-3">
                        <div className="modal-body text-center p-4 p-md-5">
                            <div className="cm-icon-wrap mx-auto mb-3">
                                <span className="cm-icon">!</span>
                            </div>

                            <p id="cm-title" className="cm-message fw-semibold text-secondary mb-4">
                                Bạn có chắc chắn muốn mua sản phẩm này?
                            </p>

                            <div className="d-flex justify-content-center gap-3">
                                <button type="button" className="btn btn-primary px-4" onClick={onConfirm}>
                                    ĐỒNG Ý
                                </button>
                                <button type="button" className="btn btn-danger px-4" onClick={onClose}>
                                    HỦY BỎ
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </>
    );
};

export default ConfirmPurchaseModal;
